import numpy as np
def components(g):
    g=np.array(g); lab=np.zeros_like(g,-1); n=0
    from collections import deque
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j]!=0 and lab[i,j]==0:
                q=deque([(i,j)]); lab[i,j]=n
                while q:
                    y,x=q.popleft()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<g.shape[0] and 0<=b<g.shape[1] and g[a,b]!=0 and lab[a,b]==0:
                            lab[a,b]=n; q.append((a,b))
                n+=1
    return lab,n
def f(g,dir_):
    # dir_: 'down','up','left','right'. 2-line defines anchor side.
    lab,n=components(g)
    comps=[]
    for c in range(n):
        ys,xs=np.where(lab==c)
        ys=list(map(int,ys)); xs=list(map(int,xs))
        comps.append((min(ys),min(xs),[(y,x) for y,x in zip(ys,xs)]))
    h,w=g.shape
    def free(cells):
        for y,x in cells:
            if not(0<=y<h and 0<=x<w): return False
        return True
    moved=True
    while moved:
        moved=False
        for cy,cx,cells in comps:
            ny,nx=[(y+dr,x+dc) for y,x,dr,dc in [(y,x,g.shape[0]-1-y if dir_=='up' else y, x, 0) for y,x in [(0,0)]]]
            # build shift vector
            dr,dc={'down':(1,0),'up':(-1,0),'left':(0,-1),'right':(0,1)}[dir_]
            t=[(y+dr,x+dc) for y,x in cells]
            if free(t) and any(not(0<=ty<h and 0<=tx<w) for ty,tx in t): pass
            ok=True
            for ty,tx in t:
                if not(0<=ty<h and 0<=tx<w): ok=False;break
                # overlap with other components?
                if any(abs(ty-cyy)==0 and abs(tx-cxx)==0 for cyy,cxx,ccells in comps if ccells!=cells): ok=False;break
            if ok and cells!=t:
                cells=t; moved=True
    res=np.full((h,w),0)
    for cy,cx,cells in comps: res[tuple(zip(*cells))]=g[tuple(zip(*cells))]
    return res.tolist()
