# components (4-conn same color), slide right maximally, blocked by 2s and other comps, order: decreasing maxcol
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # components via BFS over nonzero non-2 cells
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v!=0 and v!=2 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]; mc=-1; mn=None
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    if b+1<W and g[a][b+1]==v and not seen[a][b+1]: seen[a][b+1]=True; st.append((a,b+1))
                    if a+1<H and g[a+1][b]==v and not seen[a+1][b]: seen[a+1][b]=True; st.append((a+1,b))
                    mc=max(mc,max(b for _,b in cells))
                comps.append((cells,v,mc))
    out=[[2 if g[i][j]==2 else 0 for j in range(W)] for i in range(H)]
    # order by decreasing maxcol
    for cells,v,m in sorted(comps,key=lambda c:-c[2]):
        # try shifting right
        sh=0
        while True:
            ok=True
            for a,b in cells:
                nb=b+sh+1
                if nb>=W: ok=False;break
                tg=out[a][nb]
                if tg==v and (a,b)!=(cells[0][0],cells[0][1]): ok=False;break
                if tg!=0 and tg!=2: ok=False;break
            if not ok: break
            sh+=1
