def grav(t, bar_col=None):
    h,w=len(t),len(t[0])
    out=[[0]*w for _ in range(h)]
    seqs=[[] for _ in range(w)]
    for i in range(h):
        for j in range(w):
            if t[i][j]!=0: seqs[j].append((i,t[i][j]))
    for j in range(w):
        seq=[v for _,v in seqs[j]]
        if not seq: continue
        # pack flush against bar column
        for k,v in enumerate(seq):
            out[i][w-1-len(seq)+k]=v
    return out
