            n=len(seq)
            for m,v in enumerate(seq): out[br+1+m][j]=v
    else:
        for i in range(h):
            seq=[t[i][k] for k in range(w) if k!=bc and t[i][k]!=0]
            n=len(seq)
            for m,v in enumerate(seq): out[i][bc-n+m]=v
